print("Edition: signature")
events = [(1, 4), (3, 6), (11, 5), (13, 7), (21, 3)]
windows = {}
for t, v in events:
    w = (t // 10) * 10
    windows.setdefault(w, []).append(v)
for w in sorted(windows):
    vals = windows[w]
    print("window", w, "count", len(vals), "average", sum(vals) / len(vals))
print("RESULT events grouped into tumbling windows with per-window averages")
